public class binarytrees {
    private static final class TreeNode {
        final TreeNode left;
        final TreeNode right;

        TreeNode(TreeNode left, TreeNode right) {
            this.left = left;
            this.right = right;
        }
    }

    private static TreeNode bottomUpTree(int depth) {
        if (depth > 0) {
            return new TreeNode(
                    bottomUpTree(depth - 1),
                    bottomUpTree(depth - 1)
            );
        }
        return new TreeNode(null, null);
    }

    private static long itemCheck(TreeNode node) {
        if (node.left == null) {
            return 1;
        }
        return 1 + itemCheck(node.left) + itemCheck(node.right);
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);

        TreeNode stretchTree = bottomUpTree(n + 1);
        System.out.println("stretch tree of depth " + (n + 1)
                + "\t check: " + itemCheck(stretchTree));
        stretchTree = null;

        TreeNode longLivedTree = bottomUpTree(n);

        for (int depth = 4; depth <= n; depth += 2) {
            long iterations = 1L << (n - depth + 4);
            long check = 0;

            for (long i = 0; i < iterations; i++) {
                TreeNode tree = bottomUpTree(depth);
                check += itemCheck(tree);
            }

            System.out.println(iterations + "\t trees of depth " + depth
                    + "\t check: " + check);
        }

        System.out.println("long lived tree of depth " + n
                + "\t check: " + itemCheck(longLivedTree));
    }
}
