import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Formatter;
import java.util.Locale;

public class knucleotide {
    private static final char[] BASES = {'A', 'C', 'G', 'T'};

    private static int baseIndex(char c) {
        switch (c) {
            case 'A': return 0;
            case 'C': return 1;
            case 'G': return 2;
            case 'T': return 3;
            default: return -1;
        }
    }

    private static String twoMer(int value) {
        return new String(new char[] {
            BASES[(value >> 2) & 3],
            BASES[value & 3]
        });
    }

    private static int countOccurrences(String sequence, String fragment) {
        int count = 0;
        int from = 0;
        while (true) {
            int index = sequence.indexOf(fragment, from);
            if (index < 0) {
                return count;
            }
            count++;
            from = index + 1;
        }
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        StringBuilder input = new StringBuilder();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        boolean sawHeader = false;
        boolean inThree = false;
        String line;

        while ((line = reader.readLine()) != null) {
            if (line.startsWith(">")) {
                sawHeader = true;
                inThree = line.startsWith(">THREE");
                continue;
            }

            if (sawHeader && !inThree) {
                continue;
            }

            for (int i = 0; i < line.length(); i++) {
                char c = Character.toUpperCase(line.charAt(i));
                if (c == 'A' || c == 'C' || c == 'G' || c == 'T') {
                    input.append(c);
                }
            }
        }

        String sequence = input.toString();
        int length = sequence.length();

        int[] oneCounts = new int[4];
        int[] twoCounts = new int[16];

        for (int i = 0; i < length; i++) {
            int first = baseIndex(sequence.charAt(i));
            oneCounts[first]++;

            if (i + 1 < length) {
                int second = baseIndex(sequence.charAt(i + 1));
                twoCounts[(first << 2) | second]++;
            }
        }

        Integer[] oneOrder = new Integer[4];
        for (int i = 0; i < 4; i++) {
            oneOrder[i] = i;
        }
        Arrays.sort(oneOrder, new Comparator<Integer>() {
            @Override
            public int compare(Integer a, Integer b) {
                int byCount = Integer.compare(oneCounts[b], oneCounts[a]);
                return byCount != 0
                        ? byCount
                        : Character.compare(BASES[a], BASES[b]);
            }
        });

        Integer[] twoOrder = new Integer[16];
        for (int i = 0; i < 16; i++) {
            twoOrder[i] = i;
        }
        Arrays.sort(twoOrder, new Comparator<Integer>() {
            @Override
            public int compare(Integer a, Integer b) {
                int byCount = Integer.compare(twoCounts[b], twoCounts[a]);
                return byCount != 0
                        ? byCount
                        : twoMer(a).compareTo(twoMer(b));
            }
        });

        StringBuilder output = new StringBuilder();
        Formatter formatter = new Formatter(output, Locale.US);

        double oneDenominator = length;
        for (int index : oneOrder) {
            double percentage = oneDenominator == 0
                    ? 0.0
                    : oneCounts[index] * 100.0 / oneDenominator;
            formatter.format("%c %.3f%n", BASES[index], percentage);
        }
        output.append('\n');

        double twoDenominator = Math.max(0, length - 1);
        for (int index : twoOrder) {
            double percentage = twoDenominator == 0
                    ? 0.0
                    : twoCounts[index] * 100.0 / twoDenominator;
            formatter.format("%s %.3f%n", twoMer(index), percentage);
        }
        output.append('\n');

        String[] fragments = {
            "GGT",
            "GGTA",
            "GGTATT",
            "GGTATTTTAATT",
            "GGTATTTTAATTTATAGT"
        };

        for (String fragment : fragments) {
            output.append(countOccurrences(sequence, fragment))
                  .append('\t')
                  .append(fragment)
                  .append('\n');
        }

        formatter.close();
        System.out.print(output);
    }
}
