                    double dx = x[i] - x[j];
                    double dy = y[i] - y[j];
                    double dz = z[i] - z[j];
                    double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
                    double mag = DT / (distance * distance * distance);

