    static double energy(double[] x, double[] y, double[] z,
                         double[] vx, double[] vy, double[] vz,
                         double[] mass) {
        double e = 0.0;

        for (int i = 0; i < 5; i++) {
            e += 0.5 * mass[i] *
                    (vx[i] * vx[i] + vy[i] * vy[i] + vz[i] * vz[i]);

            for (int j = i + 1; j < 5; j++) {
                double dx = x[i] - x[j];
                double dy = y[i] - y[j];
                double dz = z[i] - z[j];
                double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
                e -= (mass[i] * mass[j]) / distance;
            }
        }

        return e;
    }
}
