        int nDigits = Integer.parseInt(args[0]);

        BigInteger q = BigInteger.ONE;
        BigInteger r = BigInteger.ZERO;
        BigInteger t = BigInteger.ONE;
        BigInteger n = BigInteger.valueOf(3);

        long k = 1;
        long l = 3;

        BigInteger ten = BigInteger.TEN;
        BigInteger two = BigInteger.valueOf(2);
        BigInteger three = BigInteger.valueOf(3);
        BigInteger four = BigInteger.valueOf(4);

        StringBuilder output = new StringBuilder(nDigits + (nDigits / 10) * 8);
        StringBuilder group = new StringBuilder(10);
        int produced = 0;

        while (produced < nDigits) {
            if (q.multiply(four).add(r).subtract(t)
                    .compareTo(n.multiply(t)) < 0) {

                int digit = n.intValue();
                group.append((char) ('0' + digit));
                produced++;

                if (group.length() == 10 || produced == nDigits) {
                    output.append(group)
                          .append('\t')
                          .append(':')
                          .append(produced)
                          .append('\n');
                    group.setLength(0);
                }

                BigInteger nextR = r.subtract(n.multiply(t)).multiply(ten);
                BigInteger nextN = q.multiply(three)
                        .add(r)
                        .multiply(ten)
                        .divide(t)
                        .subtract(n.multiply(ten));

                q = q.multiply(ten);
                r = nextR;
                n = nextN;
            } else {
                BigInteger lValue = BigInteger.valueOf(l);

                BigInteger nextR = q.shiftLeft(1)
                        .add(r)
                        .multiply(lValue);

                BigInteger nextN = q.multiply(BigInteger.valueOf(7 * k))
                        .add(two)
                        .add(r.multiply(lValue))
                        .divide(t.multiply(lValue));

                q = q.multiply(BigInteger.valueOf(k));
                t = t.multiply(lValue);
                r = nextR;
                n = nextN;

                k++;
                l += 2;
            }
        }

        System.out.print(output);
    }
}
