        "agggta[cgt]a|t[acg]taccct",
        "agggtaa[cgt]|[acg]ttaccct"
    };

    private static final Pattern[] COMPILED_COUNT_PATTERNS = new Pattern[COUNT_PATTERNS.length];

    static {
        for (int i = 0; i < COUNT_PATTERNS.length; i++) {
            COMPILED_COUNT_PATTERNS[i] = Pattern.compile(COUNT_PATTERNS[i]);
        }
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        byte[] input = readAll(System.in);
        int originalLength = input.length;

        byte[] strippedBytes = stripFasta(input);
        int strippedLength = strippedBytes.length;
        String sequence = new String(strippedBytes, StandardCharsets.ISO_8859_1);

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < COUNT_PATTERNS.length; i++) {
            Matcher matcher = COMPILED_COUNT_PATTERNS[i].matcher(sequence);
            int count = 0;
            while (matcher.find()) {
                count++;
            }
            output.append(COUNT_PATTERNS[i]).append(' ').append(count).append('\n');
        }

        String substituted = sequence;
        substituted = substituted.replaceAll("tHa[Nt]", "<4>");
        substituted = substituted.replaceAll("aND|caN|Ha[DS]|WaS", "<3>");
        substituted = substituted.replaceAll("a[NSt]|BY", "<2>");
        substituted = substituted.replaceAll("<[^>]*>", "|");
        substituted = substituted.replaceAll("\\|[^|][^|]*\\|", "-");

        output.append('\n')
              .append(originalLength).append('\n')
              .append(strippedLength).append('\n')
              .append(substituted.length()).append('\n');

        System.out.print(output);
    }

    private static byte[] readAll(InputStream in) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buffer = new byte[8192];
        int read;
        while ((read = in.read(buffer)) != -1) {
            out.write(buffer, 0, read);
        }
        return out.toByteArray();
    }

    private static byte[] stripFasta(byte[] input) {
        byte[] result = new byte[input.length];
        int out = 0;
        int i = 0;

        while (i < input.length) {
            if (input[i] == '>') {
                int newline = i;
                while (newline < input.length && input[newline] != '\n') {
                    newline++;
                }

                if (newline < input.length) {
                    i = newline + 1;
                    continue;
                }
            }

            if (input[i] != '\n') {
                result[out++] = input[i];
            }
            i++;
        }

        byte[] trimmed = new byte[out];
        System.arraycopy(result, 0, trimmed, 0, out);
        return trimmed;
    }
