import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.IOException;

public class revcomp {
    private static final byte[] COMPLEMENT = new byte[256];

    static {
        for (int i = 0; i < 256; i++) {
            COMPLEMENT[i] = (byte) i;
        }

        set('A', 'T'); set('T', 'A');
        set('C', 'G'); set('G', 'C');
        set('U', 'A');
        set('R', 'Y'); set('Y', 'R');
        set('K', 'M'); set('M', 'K');
        set('B', 'V'); set('V', 'B');
        set('D', 'H'); set('H', 'D');
        set('S', 'S'); set('W', 'W'); set('N', 'N');

        set('a', 't'); set('t', 'a');
        set('c', 'g'); set('g', 'c');
        set('u', 'a');
        set('r', 'y'); set('y', 'r');
        set('k', 'm'); set('m', 'k');
        set('b', 'v'); set('v', 'b');
        set('d', 'h'); set('h', 'd');
        set('s', 's'); set('w', 'w'); set('n', 'n');
    }

    private static void set(char from, char to) {
        COMPLEMENT[from] = (byte) to;
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        BufferedInputStream in = new BufferedInputStream(System.in);
        BufferedOutputStream out = new BufferedOutputStream(System.out);

        byte[] line = new byte[1024];
        int lineLength = 0;

        Sequence sequence = new Sequence();
        IntList lineWidths = new IntList();
        boolean haveRecord = false;

        int value;
        while ((value = in.read()) != -1) {
            if (value == '\n') {
                if (lineLength > 0 && line[lineLength - 1] == '\r') {
                    lineLength--;
                }

                if (lineLength > 0 && line[0] == '>') {
                    if (haveRecord) {
                        writeSequence(sequence, lineWidths, out);
                        sequence = new Sequence();
                        lineWidths.clear();
                    }

                    out.write(line, 0, lineLength);
                    out.write('\n');
                    haveRecord = true;
                } else {
                    sequence.append(line, lineLength);
                    lineWidths.add(lineLength);
                }

                lineLength = 0;
            } else {
                if (lineLength == line.length) {
                    byte[] expanded = new byte[line.length * 2];
                    System.arraycopy(line, 0, expanded, 0, line.length);
                    line = expanded;
                }
                line[lineLength++] = (byte) value;
            }
        }

        if (lineLength > 0) {
            if (line[lineLength - 1] == '\r') {
                lineLength--;
            }

            if (lineLength > 0 && line[0] == '>') {
                if (haveRecord) {
                    writeSequence(sequence, lineWidths, out);
                    sequence = new Sequence();
                    lineWidths.clear();
                }

                out.write(line, 0, lineLength);
                out.write('\n');
                haveRecord = true;
            } else {
                sequence.append(line, lineLength);
                lineWidths.add(lineLength);
            }
        }

        if (haveRecord) {
            writeSequence(sequence, lineWidths, out);
        }

        out.flush();
    }

    private static void writeSequence(
            Sequence sequence,
            IntList widths,
            BufferedOutputStream out) throws IOException {

        int total = sequence.size;
        int sourceIndex = total - 1;
        byte[] outputLine = new byte[1024];

        for (int i = 0; i < widths.size; i++) {
            int width = widths.values[i];

            if (outputLine.length < width) {
                outputLine = new byte[width];
            }

            for (int j = 0; j < width; j++) {
                outputLine[j] = COMPLEMENT[sequence.data[sourceIndex--] & 0xff];
            }

            out.write(outputLine, 0, width);
            out.write('\n');
        }
    }

    private static final class Sequence {
        private byte[] data = new byte[1024];
        private int size;

        void append(byte[] source, int length) {
            ensureCapacity(size + length);
            System.arraycopy(source, 0, data, size, length);
            size += length;
        }

        private void ensureCapacity(int required) {
            if (required <= data.length) {
                return;
            }

            int capacity = data.length;
            while (capacity < required) {
                capacity *= 2;
            }

            byte[] expanded = new byte[capacity];
            System.arraycopy(data, 0, expanded, 0, size);
            data = expanded;
        }
    }

    private static final class IntList {
        private int[] values = new int[16];
        private int size;

        void add(int value) {
            if (size == values.length) {
                int[] expanded = new int[values.length * 2];
                System.arraycopy(values, 0, expanded, 0, size);
                values = expanded;
            }
            values[size++] = value;
        }

        void clear() {
            size = 0;
        }
    }
}
