import java.util.Arrays;
import java.util.Locale;

public class spectralnorm {
    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);

        double[] u = new double[n];
        double[] v = new double[n];
        double[] w = new double[n];

        Arrays.fill(u, 1.0);

        for (int iteration = 0; iteration < 10; iteration++) {
            // v = A * u
            for (int i = 0; i < n; i++) {
                double sum = 0.0;
                int denominator = i * (i + 1) / 2 + i + 1;

                for (int j = 0; j < n; j++) {
                    sum += u[j] / denominator;
                    denominator += i + j + 1;
                }
                v[i] = sum;
            }

            // w = A^T * v
            Arrays.fill(w, 0.0);
            for (int i = 0; i < n; i++) {
                double value = v[i];
                int denominator = i * (i + 1) / 2 + i + 1;

                for (int j = 0; j < n; j++) {
                    w[j] += value / denominator;
                    denominator += i + j + 1;
                }
            }

            double[] temp = u;
            u = w;
            w = temp;
        }

        double numerator = 0.0;
        double denominator = 0.0;

        for (int i = 0; i < n; i++) {
            numerator += u[i] * u[i];
            denominator += v[i] * v[i];
        }

        Locale.setDefault(Locale.US);
        System.out.printf("%.9f%n", Math.sqrt(numerator / denominator));
    }
}
